@startuml
class Location {
  +address : string
}

class Driver {
  +firstName : string
  +lastName : string
}

class Vehicle {
  +vehicleNumber : string
}

class Truck extends Vehicle {
  +weight : float
}

class Car extends Vehicle {
  +seats : int
}

class Van extends Vehicle {
}

class Order {
  +date : date
}

Location "1" *-- "*" Driver
Location "1" *-- "*" Vehicle
Location "1" -- "1" origin : origin
Location "1" -- "1" destination : destination
Order "1" -- "1" origin : origin
Order "1" -- "1" destination : destination
Driver "1" -- "0..1" Order : carries out
Driver "0..1" -- "*" Vehicle : drives
@enduml

